export interface HttpHeaders {
  [key: string]: string;
}

export interface Transaction {
  transactionId: string;
  date: string;
  description: string;
  amount: number;
  currency: CurrencyCode | string;
  category?: string;
  status: TransactionStatus | string;
  merchantName?: string;
  merchantCategoryCode?: string;
  referenceNumber?: string;
  isDisputed?: boolean;
}

export interface Account {
  accountId: string;
  accountNumberMasked: string;
  routingNumberMasked?: string;
  accountName: string;
  accountType: AccountType | string;
  balance: number;
  availableBalance: number;
  currency: CurrencyCode | string;
  status: AccountStatus | string;
  interestRate?: number;
  openedDate: string;
  lastUpdated: string;
  branchId?: string;
  isJointAccount: boolean;
  recentTransactions?: Transaction[];
  metadata?: Record<string, any>;
}

export interface AccountGroupSummary {
  groupId: string;
  groupName: string;
  totalAssets: number;
  totalLiabilities: number;
  netWorth: number;
  currency: CurrencyCode | string;
  accounts: Account[];
  refreshTimestamp: string;
  lastStatementDate?: string;
  primaryOwnerId: string;
  coOwnerIds?: string[];
}

export interface CreditCard {
  cardId: string;
  cardName: string;
  cardNumberLastFour: string;
  network: CardNetwork | string;
  outstandingBalance: number;
  creditLimit: number;
  availableCredit: number;
  cashAdvanceLimit: number;
  cashAdvanceAvailable: number;
  dueDate: string;
  minimumPaymentDue: number;
  lastStatementBalance: number;
  apr: number;
  cashAdvanceApr: number;
  status: CreditCardStatus | string;
  rewardsBalance?: number;
  rewardsCurrency?: string;
  openedDate: string;
  expiryDate: string;
  isPrimary: boolean;
  authorizedUsers?: string[];
  contactlessEnabled?: boolean;
}

export interface CreditCardAccountSummary {
  summaryId: string;
  totalCreditLimit: number;
  totalOutstandingBalance: number;
  totalAvailableCredit: number;
  totalMinimumPaymentDue: number;
  currency: CurrencyCode | string;
  cards: CreditCard[];
  refreshTimestamp: string;
  primaryOwnerId: string;
}

export interface AccountSummaryRow {
  rowId: string;
  timestamp: Date;
  method: string;
  url: string;
  statusCode: number;
  requestHeaders: HttpHeaders;
  responseHeaders: HttpHeaders;
  accountGroupSummary: AccountGroupSummary | null;
  creditCardAccountSummary: CreditCardAccountSummary | null;
  rawRow?: string[];
  processingTimeMs?: number;
  clientIp?: string;
  userAgent?: string;
  correlationId?: string;
}

export interface AccountSummaryState {
  accountGroupSummary: AccountGroupSummary | null;
  creditCardSummary: CreditCardAccountSummary | null;
  isLoading: boolean;
  isSyncing: boolean;
  error: AccountSummaryError | null;
  lastFetched: Date | null;
  activeFilters: {
    accountTypes: AccountType[];
    statuses: AccountStatus[];
    currency?: CurrencyCode;
  };
}

