export const HttpHeadersSchema = z.record(z.string(), z.string());

export const TransactionSchema = z.object({
  transactionId: z.string().uuid().or(z.string().min(5)),
  date: z.string().datetime({ offset: true }).or(z.string()),
  description: z.string().min(1),
  amount: z.number(),
  currency: z.nativeEnum(CurrencyCode).or(z.string()),
  category: z.string().optional(),
  status: z.nativeEnum(TransactionStatus).or(z.string()),
  merchantName: z.string().optional(),
  merchantCategoryCode: z.string().optional(),
  referenceNumber: z.string().optional(),
  isDisputed: z.boolean().optional(),
});

export const AccountSchema = z.object({
  accountId: z.string().min(1),
  accountNumberMasked: z.string().min(4),
  routingNumberMasked: z.string().optional(),
  accountName: z.string().min(1),
  accountType: z.nativeEnum(AccountType).or(z.string()),
  balance: z.number(),
  availableBalance: z.number(),
  currency: z.nativeEnum(CurrencyCode).or(z.string()),
  status: z.nativeEnum(AccountStatus).or(z.string()),
  interestRate: z.number().min(0).max(100).optional(),
  openedDate: z.string().datetime({ offset: true }).or(z.string()),
  lastUpdated: z.string().datetime({ offset: true }).or(z.string()),
  branchId: z.string().optional(),
  isJointAccount: z.boolean(),
  recentTransactions: z.array(TransactionSchema).optional(),
  metadata: z.record(z.string(), z.any()).optional(),
});

export const AccountGroupSummarySchema = z.object({
  groupId: z.string().uuid().or(z.string().min(1)),
  groupName: z.string().min(1),
  totalAssets: z.number(),
  totalLiabilities: z.number(),
  netWorth: z.number(),
  currency: z.nativeEnum(CurrencyCode).or(z.string()),
  accounts: z.array(AccountSchema),
  refreshTimestamp: z.string().datetime({ offset: true }).or(z.string()),
  lastStatementDate: z.string().datetime({ offset: true }).or(z.string()).optional(),
  primaryOwnerId: z.string().min(1),
  coOwnerIds: z.array(z.string()).optional(),
});

export const CreditCardSchema = z.object({
  cardId: z.string().min(1),
  cardName: z.string().min(1),
  cardNumberLastFour: z.string().length(4),
  network: z.nativeEnum(CardNetwork).or(z.string()),
  outstandingBalance: z.number(),
  creditLimit: z.number().min(0),
  availableCredit: z.number(),
  cashAdvanceLimit: z.number().min(0),
  cashAdvanceAvailable: z.number(),
  dueDate: z.string().datetime({ offset: true }).or(z.string()),
  minimumPaymentDue: z.number().min(0),
  lastStatementBalance: z.number(),
  apr: z.number().min(0).max(100),
  cashAdvanceApr: z.number().min(0).max(100),
  status: z.nativeEnum(CreditCardStatus).or(z.string()),
  rewardsBalance: z.number().min(0).optional(),
  rewardsCurrency: z.string().optional(),
  openedDate: z.string().datetime({ offset: true }).or(z.string()),
  expiryDate: z.string().regex(/^(0[1-9]|1[0-2])\/?([0-9]{2}|[0-9]{4})$/, "Invalid expiry date format (MM/YY or MM/YYYY)"),
  isPrimary: z.boolean(),
  authorizedUsers: z.array(z.string()).optional(),
  contactlessEnabled: z.boolean().optional(),
});

export const CreditCardAccountSummarySchema = z.object({
  summaryId: z.string().uuid().or(z.string().min(1)),
  totalCreditLimit: z.number().min(0),
  totalOutstandingBalance: z.number(),
  totalAvailableCredit: z.number(),
  totalMinimumPaymentDue: z.number().min(0),
  currency: z.nativeEnum(CurrencyCode).or(z.string()),
  cards: z.array(CreditCardSchema),
  refreshTimestamp: z.string().datetime({ offset: true }).or(z.string()),
  primaryOwnerId: z.string().min(1),
});

export const AccountSummaryRowSchema = z.object({
  rowId: z.string().uuid().or(z.string().min(1)),
  timestamp: z.date(),
  method: z.string().min(1),
  url: z.string().url().or(z.string().startsWith('/')),
  statusCode: z.number().int().min(100).max(599),
  requestHeaders: HttpHeadersSchema,
  responseHeaders: HttpHeadersSchema,
  accountGroupSummary: AccountGroupSummarySchema.nullable(),
  creditCardAccountSummary: CreditCardAccountSummarySchema.nullable(),
  rawRow: z.array(z.string()).optional(),
  processingTimeMs: z.number().int().min(0).optional(),
  clientIp: z.string().ip().optional(),
  userAgent: z.string().optional(),
  correlationId: z.string().uuid().optional(),
});

