export enum ErrorCodes {
  VALIDATION_FAILED = 'VALIDATION_FAILED',
  NETWORK_ERROR = 'NETWORK_ERROR',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  INTERNAL_SERVER_ERROR = 'INTERNAL_SERVER_ERROR',
  PARSE_ERROR = 'PARSE_ERROR',
  RATE_LIMITED = 'RATE_LIMITED',
  TIMEOUT = 'TIMEOUT',
}

export class AccountSummaryError extends Error {
  public readonly code: ErrorCodes | string;
  public readonly statusCode?: number;
  public readonly details?: any;
  public readonly timestamp: Date;

  constructor(message: string, code: ErrorCodes | string, statusCode?: number, details?: any) {
    super(message);
    this.name = 'AccountSummaryError';
    this.code = code;
    this.statusCode = statusCode;
    this.details = details;
    this.timestamp = new Date();
    
    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, AccountSummaryError);
    } else {
      Object.setPrototypeOf(this, AccountSummaryError.prototype);
    }
  }

  public toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      statusCode: this.statusCode,
      details: this.details,
      timestamp: this.timestamp.toISOString(),
      stack: this.stack,
    };
  }
}

