      // Simulating async parsing to prevent blocking the main thread on large files
      const parsed = await new Promise<AccountSummaryRow[]>((resolve, reject) => {
        try {
          setTimeout(() => {
            resolve(parseAccountSummaryCsv(csvContent));
          }, 10);
        } catch (e) {
          reject(e);
        }
      });
      setSummaryRows(parsed);
